CalcModel   4
ReStart   0
CalcSpec   0
CalcEigenVec   0
InitialVecType   0
InputEigenVec   0
OutputEigenVec   0
InputHam   0
OutputHam   0
OutputExVec   0
EOF

cat > namelist.def <<EOF
ModPara         modpara.def
LocSpin         locspn.def
Trans           trans.def
